import sys, json
try:
    d = json.load(sys.stdin)
    r = json.loads(d['result'])
    exps = r['data']['experiments']
    fitd_exps = {}
    for k in sorted(exps.keys()):
        e = exps[k]
        m = e.get('metrics', {})
        ms = json.dumps(m)
        if 'fitd' in ms.lower() or 'fitd' in k.lower():
            fitd_exps[k] = e

    print(f'Total FITD-related experiments: {len(fitd_exps)}')
    for k in list(fitd_exps.keys())[:5]:
        e = fitd_exps[k]
        print(f'\n=== {k} (status={e.get(\"status\")}, conclusion={e.get(\"conclusion\")}) ===')
        m = e.get('metrics', {})
        for mk in sorted(m.keys()):
            if 'fitd' in mk.lower():
                print(f'{mk}: {m[mk]}')
except Exception as e:
    print(f'Error: {e}')
